/**
 * A recorded motion: joint positions sampled at a fixed rate. Plain JSON on
 * disk so it can be inspected, trimmed, or generated by hand.
 */
export interface Trajectory {
  readonly hz: number;
  readonly ids: readonly number[];
  /** One entry per sample, each holding one position per id, in `ids` order. */
  readonly frames: readonly (readonly number[])[];
  readonly recorded?: string;
}

export function serializeTrajectory(trajectory: Trajectory): string {
  return JSON.stringify(trajectory, null, 1);
}

export function parseTrajectory(text: string): Trajectory {
  let data: unknown;
  try {
    data = JSON.parse(text);
  } catch {
    throw new Error("not valid JSON");
  }
  if (typeof data !== "object" || data === null) throw new Error("expected an object");
  const { hz, ids, frames, recorded } = data as Record<string, unknown>;
  if (typeof hz !== "number" || !(hz >= 1 && hz <= 100)) throw new Error("hz must be between 1 and 100");
  if (
    !Array.isArray(ids) ||
    ids.length === 0 ||
    !ids.every((id) => Number.isInteger(id) && id >= 0 && id <= 253) ||
    new Set(ids).size !== ids.length
  ) {
    throw new Error("ids must be a non-empty list of distinct servo ids");
  }
  if (!Array.isArray(frames) || frames.length === 0) throw new Error("frames must be a non-empty list");
  for (const [index, frame] of frames.entries()) {
    if (!Array.isArray(frame) || frame.length !== ids.length || !frame.every((p) => Number.isInteger(p))) {
      throw new Error(`frame ${index} must hold ${ids.length} integer positions`);
    }
  }
  return { hz, ids, frames, ...(typeof recorded === "string" ? { recorded } : {}) };
}

/** Keep every position inside the servo's own limits, so a replay can never push a joint past a hard stop. */
export function clampFrame(frame: readonly number[], limits: readonly (readonly [number, number])[]): number[] {
  return frame.map((position, i) => {
    const [min, max] = limits[i]!;
    return Math.min(max, Math.max(min, position));
  });
}

export function durationSeconds(trajectory: Trajectory): number {
  return trajectory.frames.length / trajectory.hz;
}

/** The largest change of any joint between consecutive frames, in ticks. */
export function largestStep(trajectory: Trajectory): number {
  let largest = 0;
  for (let i = 1; i < trajectory.frames.length; i++) {
    const prev = trajectory.frames[i - 1]!, next = trajectory.frames[i]!;
    for (let j = 0; j < prev.length; j++) largest = Math.max(largest, Math.abs(next[j]! - prev[j]!));
  }
  return largest;
}
